float strokeWithBlur(float x, float s, float w, float blur)
{
	float d = smoothstep(s, s + blur, x + w * 0.5) - smoothstep(s, s + blur, x - w * 0.5);
	return clamp(d, 0.0, 1.0);
}

float stroke(float x, float s, float w)
{
	float d = step(s, x + w * 0.5) - step(s, x - w * 0.5);
	return clamp(d, 0.0, 1.0);
}

float fillWithBlur(float x, float size, float blur)
{
