}


float fill(float x, float size)
{
	return 1.0 - step(size, x);
}

float sdCircle(vec2 uv, float r){
	return length(uv) - r;
}

float sdRect(vec2 uv, vec2 s){
	vec2 q = abs(uv) - s;
	return length(max(q,0.0)) + min(max(q.x,q.y),0.0);
}

float sdVesica(vec2 uv, float r, float w){
	vec2 offset = vec2(w*0.5, 0.0);
	return max(sdCircle(uv - offset, r), sdCircle(uv + offset, r));
}

vec4 baseRibbon(vec2 uv){
	vec4 color = vec4(0.0);
	float c = sdCircle(uv*vec2(0.6, 1.2), 0.1);
	float maskY = smoothstep(0.4, 0.9, uv.y * 0.5 + 0.5);
	float maskX = 1.0 - smoothstep(0.3, 0.15, abs(uv.x));
	float baseRing = strokeWithBlur(c, 0.1, 0.03, 0.1);
	color += maskX*maskY*pow(baseRing, 4.0);
	// color *= vec4(1.0, 0.6, 0.7, 1.0);
	color *= vec4(vec3(u_col1), 1.0);
	return color;
}

vec4 vesicaRibbon12(vec2 uv){
	vec4 color = vec4(0.0);
	float n = 12.0;
	float a = (acos(-1.0)*2.0)/n;
	float vscs = 10e8;
	float sVscs = 10e8;
	for(float i = 0.0; i < 12.0; i+=1.0){
		vec2 p = uv;
		p *= rotate(a*i);
		p.y -= 0.5;
		float vsc = sdVesica(p, 0.3, 0.1);
		color += pow(strokeWithBlur(vsc, 0.1, 0.04, 0.08), 2.0);
		vscs = min(vscs, vsc);
	}
	color += fillWithBlur(vscs, 0.0, 0.1);

	return color;
}

vec4 rectRibbon2(vec2 uv){
	vec4 color = vec4(0.0);
	float r1 = sdRect(uv, vec2(0.4));
	float r12 = sdRect(uv, vec2(0.38));
	float r2 = sdRect(uv*rotate(pi*0.25), vec2(0.4));
	float r22 = sdRect(uv*rotate(pi*0.25), vec2(0.38));
	float d = 10e8;
	d = min(d, max(r1, -r12));
	d = min(d, max(r2, -r22));

	color += fillWithBlur(d, 0.0, 0.1);
	return color;
}

vec4 circleRibbon2(vec2 uv){
	vec4 color = vec4(0.0);
	float c1 = sdCircle(uv+vec2(0.3, 0.0), 0.2);
	float c11 = sdCircle(uv+vec2(0.3, 0.0), 0.18);
	float c2 = sdCircle(uv-vec2(0.3, 0.0), 0.2);
	float c22 = sdCircle(uv-vec2(0.3, 0.0), 0.18);
	float c3 = sdCircle(uv-vec2(0.0, 0.0), 0.3);
	float c33 = sdCircle(uv-vec2(0.0, 0.0), 0.28);
	float c4 = sdCircle(uv+vec2(0.5, 0.0), 0.15);
	float c44 = sdCircle(uv+vec2(0.5, 0.0), 0.12);
	float c5 = sdCircle(uv-vec2(0.5, 0.0), 0.15);
	float c55 = sdCircle(uv-vec2(0.5, 0.0), 0.112);
	float d = 10e8;
	d = min(d, max(c1, -c11));
	d = min(d, max(c2, -c22));
	d = min(d, max(c3, -c33));
	d = min(d, max(c4, -c44));
	d = min(d, max(c5, -c55));

	color += fillWithBlur(d, 0.0, 0.05);
	return color;
}

vec4 ribbonFunction(vec2 uv, int index){
	vec4 color = vec4(0.0);
	if(index == 0){
		color += vesicaRibbon12(uv);
	}
	else if(index == 1){
		color += rectRibbon2(uv);
	}
	else if(index == 2){
		color += circleRibbon2(uv);
	}

	return color;
}


vec4 renderingFunc(vec2 uv){
    vec4 color = vec4(0.0);

	color = mix(color, vec4(1.0), baseRibbon(uv)*100.0);
	vec2 rp = uv*vec2(resolution.x/resolution.y, 1.0)-vec2(0.0, 0.2);

	// float fr = frontRibbonDF(rp);
	// color += frontRibbon(rp)*mix(vec4(1.0, 0.8, 0.9, 1.0)*0.8, vec4(0.8, 0.8, 1.0, 1.0)*0.8, 1.0-length(rp*2.0));
	// color += ribbonFunction(rp, 0)*mix(vec4(vec3(u_col2), 1.0)*0.8, vec4(vec3(u_col3), 1.0)*0.8, 1.0-length(rp*2.0));
	// color += ribbonFunction(rp, 1)*mix(vec4(vec3(u_col2), 1.0)*0.8, vec4(vec3(u_col3), 1.0)*0.8, sin(rp.x*40.0));
	color += ribbonFunction(rp, u_index)*mix(vec4(vec3(u_col2), 1.0)*0.8, vec4(vec3(u_col3), 1.0)*0.8, sin(rp.x*4.0));

