			var col1 = [random(0.5, 0.7), random(0.5, 0.7), 1.0];
			var col2 = [random(0.5, 0.7), random(0.5, 0.7), 1.0];
			var col3 = [random(0.5, 0.7), random(0.5, 0.7), 1.0];
			flowers.push(new FlowerRect(this.vPoses[this.vPoses.length-1].x, this.vPoses[this.vPoses.length-1].y, map(lenCoef, 0.4, 0.8, random(100, 200), random(300, 400)), col1, col2, col3));
		}break;
		case 4:{
			var col1 = [1.0, 1.0, 1.0];
			var col2 = [random(0.5, 0.7), random(0.5, 0.7), random(0.5, 0.7)];
			var col3 = [random(0.5, 0.7), random(0.5, 0.7), random(0.5, 0.7)];
			flowers.push(new FlowerRect(this.vPoses[this.vPoses.length-1].x, this.vPoses[this.vPoses.length-1].y, map(lenCoef, 0.4, 0.8, random(100, 200), random(300, 400)), col1, col2, col3));
		}break;
		case 5:{
			var col1 = [1.0, 0.8, 0.8];
			var col2 = [0.7, 1.0, 0.7];
			var col3 = [0.8, 0.8, 1.0];
			flowers.push(new FlowerRect(this.vPoses[this.vPoses.length-1].x, this.vPoses[this.vPoses.length-1].y, map(lenCoef, 0.4, 0.8, random(100, 200), random(300, 400)), col1, col2, col3));
		}break;
	}

	this.display = function(){
		push();
		fill(40, 120, 30);
		noStroke();
		for(let i = 0; i < this.vPoses.length-1; i++){
			let aVector = p5.Vector.sub(this.vPoses[i+1], this.vPoses[i]);
			var a = aVector.heading();
			push();
			translate(this.vPoses[i].x, this.vPoses[i].y);
			rotate(a-HALF_PI);
			shader(stalkShader);
			stalkShader.setUniform("time", frameCount);
			stalkShader.setUniform("resolution", [this.len, this.len]);
			stalkShader.setUniform("u_col1", this.sCol);
			let addInterval = (i == this.vPoses.length-2) ? 0.0 : random(30, 60);
			rect(-this.rectW*0.5, 0, this.rectW, this.interval + addInterval + this.reviceValue*0.5);
			resetShader();
			pop();
		}
		for(let i = 0; i < this.vPoses.length; i++){
			push();
			translate(this.vPoses[i].x, this.vPoses[i].y);
			pop();
		}
		pop();
	}
}

function leafRect(x, y, len, angle)
{
	this.pos = createVector(x, y);
	this.len = len;
	this.angle = random(-TWO_PI, TWO_PI);
	this.lCol = [random(0.2), random(0.6), random(0.4), 1.0];

	this.display = function(){
		push();
		rectMode(CENTER);
		noStroke();
		fill(0, 0, 0, 255);
		shader(leafShader);
		leafShader.setUniform("u_lCol", this.lCol);
		leafShader.setUniform("angle", this.angle);
		rect(this.pos.x, this.pos.y,  this.len, this.len);
		resetShader();
		pop();
	}
}

function FlowerRect(x, y, len, pCol, cCol1, cCol2)
{
	this.pos = createVector(x, y);
	this.len = len;
	this.pCol = pCol;
	this.cCol1 = cCol1;
	this.cCol2 = cCol2;
	this.petalCoef = random([1.5, 2.0, 2.5, 3.0, 3.5, 4.0]);
	this.angle = random(-TWO_PI, TWO_PI);

	this.display = function(){
		push();
		rectMode(CENTER);
		noStroke();
		fill(0, 0, 0, 255);
		shader(useShader);
		useShader.setUniform("u_col1", this.pCol);
		useShader.setUniform("u_col2", this.cCol1);
		useShader.setUniform("u_col3", this.cCol2);
		useShader.setUniform("petalCoef", this.petalCoef);
		useShader.setUniform("angle", this.angle);
		rect(this.pos.x, this.pos.y,  this.len, this.len);
		resetShader();
		pop();
	}
}

function WhiteFlowerRect(x, y, cVal, len, p, a)
{
	this.pos = createVector(x, y);
	this.len = len;
	this.pCol = [1.0, 1.0, 1.0];
	this.cCol1 = [cVal, cVal, cVal];
	this.cCol2 = [0.0, 0.0, 0.0];
	this.petalCoef = p;
	this.angle = a;

	this.display = function(){
		push();
		rectMode(CENTER);
		noStroke();
		fill(0, 0, 0, 255);
		shader(useShader);
		useShader.setUniform("u_col1", this.pCol);
		useShader.setUniform("u_col2", this.cCol1);
		useShader.setUniform("u_col3", this.cCol2);
		useShader.setUniform("petalCoef", this.petalCoef);
		useShader.setUniform("angle", this.angle);
		rect(this.pos.x, this.pos.y,  this.len, this.len);
		resetShader();
		pop();
	}
}

function easeInOutExpo(x) {
	return x === 0
	  ? 0
	  : x === 1
		? 1
		: x < 0.5
		  ? pow(2, 20 * x - 10) / 2
		  : (2 - pow(2, -20 * x + 10)) / 2;
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +
    ".jpg");
    lapse = millis();
  }
}

